    E0 = expm(A*t(k));  E1 = expm(A*t(k + 1));  h = t(k + 1) - t(k);
    Pint = Pint + h/2*(E0'*Q*E0 + E1'*Q*E1);
    costo = costo + h/2*((E0*x0)'*Q*(E0*x0) + (E1*x0)'*Q*(E1*x0));
end
